impl ManagedLocalAiStudio {
    fn display_setup_status(&self) -> ManagedSetupStatus {
        #[cfg(feature = "visual-validation")]
        if self.visual_fixture {
            return ManagedSetupStatus::RuntimeNotInstalled;
        }
        self.setup_status.clone()
    }

    fn show_setup_action(&mut self, ui: &mut egui::Ui, status: &ManagedSetupStatus) {
        match status {
            ManagedSetupStatus::Ready => {
                match self.runtime.active_installation(self.environment) {
                    Ok(Some(installation)) => ui.small(format!(
                        "Pinned runtime: {} {} · revision {} · artifact {} · sha256 {} · compatibility {} · installed evidence {}.",
                        installation.runtime_family,
                        installation.runtime_tag,
                        installation.runtime_revision,
                        installation.artifact_name,
                        short_digest(&installation.artifact_sha256),
                        installation.compatibility_version,
                        installation.installed_unix_ms,
                    )),
                    Ok(None) => ui.small(format!(
                        "Pinned runtime: llama.cpp {PINNED_LLAMA_CPP_TAG} · revision {PINNED_LLAMA_CPP_REVISION}. Runtime artifacts are digest-verified before activation."
                    )),
                    Err(error) => ui.small(format!("Runtime provenance unavailable: {error}")),
                };
            }
            ManagedSetupStatus::RuntimeNotInstalled => {
                if ui
                    .add_enabled(self.task.is_none(), egui::Button::new("Set up Local AI"))
                    .clicked()
                {
                    self.start_task(ManagedLocalTask::install_runtime(
                        self.runtime.clone(),
                        self.environment,
                    ));
                }
                ui.small(
                    "This explicit action downloads only the pinned official runtime artifact, verifies its published SHA-256, and activates it only after verification. No model weights are acquired.",
                );
            }
            ManagedSetupStatus::WslDistributionMissing => {
                if ui
                    .add_enabled(
                        self.task.is_none(),
                        egui::Button::new("Set up dedicated WSL2 environment"),
                    )
                    .clicked()
                {
                    self.start_task(ManagedLocalTask::provision_wsl(self.runtime.clone()));
                }
                ui.small(
                    "GameEngine creates only its dedicated GameEngine-LocalAI distribution. Windows may request administrator approval; GameEngine does not bypass UAC or reboot automatically.",
                );
            }
            ManagedSetupStatus::RestartRequired => {
                if ui
                    .add_enabled(
                        self.task.is_none(),
                        egui::Button::new("Recheck after Windows restart"),
                    )
                    .clicked()
                {
                    self.start_task(ManagedLocalTask::resume_after_restart(self.runtime.clone()));
                }
                ui.small(
                    "Setup is incomplete until Windows has restarted and the prerequisite recheck succeeds. The continuation marker is machine-local.",
                );
            }
            ManagedSetupStatus::OperatingSystemPrerequisiteUnavailable(message) => {
                ui.small(format!("Prerequisite unavailable: {message}"));
            }
        }
    }

    fn show_environment_model_preparation(&mut self, ui: &mut egui::Ui, _size_bytes: u64) {
        if self.environment != ManagedExecutionEnvironment::Wsl2Linux
            || self.model_id.trim().is_empty()
        {
            return;
        }
        match self.additional_storage_bytes {
            Some(0) => {
                ui.small("WSL2 copy: verified Linux-native model cache is prepared.");
            }
            Some(bytes) => {
                ui.horizontal_wrapped(|ui| {
                    ui.small(format!(
                        "WSL2 requires an additional {} Linux-native copy.",
                        format_bytes(bytes)
                    ));
                    if ui
                        .add_enabled(
                            self.task.is_none(),
                            egui::Button::new(format!(
                                "Prepare WSL2 copy (+{})",
                                format_bytes(bytes)
                            )),
                        )
                        .clicked()
                    {
                        self.start_task(ManagedLocalTask::prepare_model(
                            self.runtime.clone(),
                            self.model_id.clone(),
                            self.environment,
                        ));
                    }
                });
                ui.small(
                    "The copy starts only from this explicit storage approval and is SHA-256 verified against the registered GGUF identity.",
                );
            }
            None => {
                ui.small("WSL2 model preparation state is unavailable; reselect the runtime or model to recheck it.");
            }
        }
    }

    fn show_wsl_removal(&mut self, ui: &mut egui::Ui) {
        if self.confirm_remove_wsl {
            ui.horizontal_wrapped(|ui| {
                ui.small(
                    "Remove only the dedicated GameEngine-LocalAI distribution and managed WSL runtime/cache? Original registered GGUF files are preserved.",
                );
                if ui
                    .add_enabled(self.task.is_none(), egui::Button::new("Remove managed WSL2"))
                    .clicked()
                {
                    self.start_task(ManagedLocalTask::remove_environment(
                        self.runtime.clone(),
                        ManagedExecutionEnvironment::Wsl2Linux,
                    ));
                }
                if ui.button("Keep").clicked() {
                    self.confirm_remove_wsl = false;
                }
            });
        } else if ui.button("Remove managed WSL2 environment…").clicked() {
            self.confirm_remove_wsl = true;
        }
    }

    fn refresh_cached_state(&mut self) {
        #[cfg(feature = "visual-validation")]
        if self.visual_fixture {
            self.setup_status = ManagedSetupStatus::RuntimeNotInstalled;
            self.additional_storage_bytes = None;
            return;
        }
        self.setup_status = self.runtime.setup_status(self.environment);
        self.additional_storage_bytes = if self.model_id.trim().is_empty() {
            None
        } else {
            self.runtime
                .additional_storage_for_environment(&self.model_id, self.environment)
                .ok()
        };
    }

    fn start_task(
        &mut self,
        task: Result<ManagedLocalTask, crate::managed_local_runtime::ManagedLocalRuntimeError>,
    ) {
        match task {
            Ok(task) => self.task = Some(task),
            Err(error) => self.status = Some(error.to_string()),
        }
    }

    #[cfg(feature = "visual-validation")]
    pub(crate) fn prepare_visual_validation(&mut self) {
        self.environment = ManagedExecutionEnvironment::WindowsNative;
        self.model_id.clear();
        self.task = None;
        self.setup_status = ManagedSetupStatus::RuntimeNotInstalled;
        self.additional_storage_bytes = None;
        self.status = None;
        self.confirm_remove_wsl = false;
        self.visual_fixture = true;
    }
}
